/*
 * Watch <-> phone AppMessage contract (C side).
 *
 * Mirrors src/common/protocol.js, which the phone (src/pkjs) uses. The message
 * KEY names are declared in package.json -> pebble.messageKeys and surface here
 * as MESSAGE_KEY_<NAME> (generated by the build). This header only carries the
 * value encoding both sides must agree on.
 *
 * Encoding (all AppMessage values are integers):
 *   HEADING            degrees 0..359, magnetic
 *   AUTOPILOT_STATE    one of ApState
 *   SOG                speed over ground, tenths of a knot (knots * 10)
 *   WIND_SPEED         apparent wind speed, tenths of a knot (knots * 10)
 *   WIND_ANGLE         degrees 0..359, apparent, relative to the bow (0 = ahead)
 *   CONNECTION_STATUS  one of ConnStatus
 *   TARGET_HEADING     autopilot target heading, degrees 0..359, or TARGET_NONE
 *   TARGET_WIND_ANGLE  autopilot target apparent wind angle, degrees 0..359
 *                      relative to the bow, or TARGET_NONE
 *   CMD_ADJUST_HEADING relative degrees: +1/-1, or a multiple of 10 (a held
 *                      button's repeated ±10 steps, coalesced) (watch -> phone)
 *   CMD_SET_STATE      target ApState to engage/disengage   (watch -> phone)
 *   CMD_RESULT         one of CmdResult                     (phone -> watch)
 */

#pragma once

#define SPEED_SCALE 10  // telemetry speeds are sent in tenths of a knot
#define TARGET_NONE (-1) // TARGET_HEADING / TARGET_WIND_ANGLE: no target known

typedef enum {
    AP_STATE_STANDBY = 0,
    AP_STATE_AUTO = 1,
    AP_STATE_WIND = 2,
    AP_STATE_ROUTE = 3,
    AP_STATE_UNKNOWN = 255,
} ApState;

typedef enum {
    CONN_NO_CONFIG = 0,
    CONN_DISCONNECTED = 1,
    CONN_CONNECTING = 2,
    CONN_CONNECTED = 3,
    CONN_AWAITING_APPROVAL = 4,
    CONN_ACCESS_DENIED = 5,
} ConnStatus;

typedef enum {
    CMD_RESULT_OK = 0,
    CMD_RESULT_FAILED = 1,
} CmdResult;
